<script setup lang="ts">
import {ref,computed} from 'vue';import {useWorkbench} from '../stores/workbench';import UiIcon from './UiIcon.vue';const s=useWorkbench(),override=ref<'L1'|'L2'|'L3'|'L4'|''>(''),reason=ref('');const levels=[{id:'L1',title:'显式参数修改',subtitle:'数值明确 · 结构不变',a:'明确',b:'参数'},{id:'L2',title:'场景语义推断',subtitle:'幅度待确认 · 结构不变',a:'推断',b:'参数'},{id:'L3',title:'参数与结构扩展',subtitle:'数值明确 · 扩展结构',a:'明确',b:'结构'},{id:'L4',title:'语义推断与结构扩展',subtitle:'幅度待确认 · 扩展结构',a:'推断',b:'结构'}];const highlight=computed(()=>{const text=s.spec?.instruction||'';const needle=s.activeEvidence;if(!needle||!text.includes(needle))return [{text,active:false}];const i=text.indexOf(needle);return [{text:text.slice(0,i),active:false},{text:needle,active:true},{text:text.slice(i+needle.length),active:false}]});function manual(){if(!override.value||!reason.value.trim())return;s.spec.level_override={level:override.value,reason:reason.value};s.markDirty();}
</script><template><div class="content-pad"><div class="panel-heading"><div><div class="eyebrow">M2 / 语义解析</div><h2>层级判定与原文依据</h2></div><span class="subtle-pill">{{s.parse?.engine||'演示规则引擎'}} · {{Number(s.parse?.elapsed_ms||0).toFixed(1)}} ms</span></div><div class="evidence-quote"><span v-for="(part,i) in highlight" :key="i"><mark v-if="part.active">{{part.text}}</mark><template v-else>{{part.text}}</template></span></div><div class="entity-row"><button v-for="(e,i) in s.parse?.entities||[]" :key="i" :class="{selected:s.activeEvidence===(e.evidence||e.text)}" @click="s.activeEvidence=e.evidence||e.text"><span>{{e.type==='bus'?'母线':e.type==='branch'?'支路':e.type==='gen'?'机组':'对象'}}</span><strong>{{e.id||e.target||e.text}}</strong><UiIcon name="search" :size="12"/></button></div><div class="section-heading"><h3>程序判定 <span class="level-chip">{{s.level}}</span></h3><span class="small-note">推断项 × 结构修改 · 由规格计算</span></div><div class="level-grid"><button v-for="l in levels" :key="l.id" type="button" class="level-card" :class="{selected:s.level===l.id,override:override===l.id}" @click="override=l.id as 'L1'|'L2'|'L3'|'L4'" :aria-label="l.id+' '+l.title+'，人工改选需填写理由'"><div><strong>{{l.id}}</strong><UiIcon v-if="s.level===l.id" name="check"/></div><h3>{{l.title}}</h3><p>{{l.subtitle}}</p></button></div><div class="notice" v-if="s.level==='待追问'"><UiIcon name="info"/><span>缺少明确调整对象，暂不生成参数条目。请在左侧补充信息。</span></div><div class="reason-bar"><span>判级依据</span><strong>{{s.spec.delta_pi.some((d:any)=>d.source==='inferred')?'存在场景推断参数':'参数修改均为明确项'}}</strong><span>＋</span><strong>{{s.spec.structural.length?'存在模型结构扩展':'没有结构修改'}}</strong></div><h3 v-if="s.spec.delta_pi.some((d:any)=>d.source==='inferred')">推断链</h3><div v-for="d in s.spec.delta_pi.filter((d:any)=>d.source==='inferred')" :key="d.id" class="inference-chain"><span class="inference-id">{{d.id}} · {{d.target}}</span><template v-for="(x,i) in d.inference_chain||[]" :key="i"><UiIcon v-if="i" name="arrow" :size="14"/><span>{{x}}</span></template><span class="inference-tag">{{d.confirmed?'已确认幅度':'幅度待确认'}}</span></div><details class="override-panel" :open="!!override"><summary>人工改选层级 · 记录理由</summary><div class="actions"><el-select v-model="override" placeholder="选择层级" class="compact-select"><el-option v-for="l in levels" :key="l.id" :label="l.id" :value="l.id"/></el-select><el-input v-model="reason" placeholder="填写改选理由" class="reason-input"/><el-button :disabled="!override||!reason.trim()" @click="manual">记录改选</el-button></div><p class="small-note" v-if="s.spec.level_override">人工显示：{{s.spec.level_override.level}} · {{s.spec.level_override.reason}}。程序判级仍为 {{s.level}}，用于测评统计。</p></details><div class="panel-bottom-actions"><span class="muted">原文依据与推断链会随规格版本保存。</span><el-button type="primary" @click="s.step=3;s.tab='spec'" data-testid="go-spec">进入规格确认 <UiIcon name="arrow" :size="15"/></el-button></div></div></template>